#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    cin >> s;
    int l = s.length();

    if (l < 2) {
        if (s == "0" || s == "_" || s == "X") {
            cout << 1 << "\n";
        } else {
            cout << 0 << "\n";
        }
        return 0;
    } else if (l == 2) {
        int count = 0;
        for (int i = 10; i <= 95; i += 5) {
            if (i % 25 != 0) continue;
            std::string str = std::to_string(i);
            if ('0' <= s[0] && s[0] <= '9') {
                if ('0' <= s[1] && s[1] <= '9') {
                    if (s == str) count++;
                } else {
                    if (s[0] == str[0]) count++;
                }
            } else if (s[0] == '_') {
                if ('0' <= s[1] && s[1] <= '9') {
                    if (s[1] == str[1]) count++;
                } else {
                    count++;
                }
            } else {
                if ('0' <= s[1] && s[1] <= '9') {
                    if (s[1] == str[1]) count++;
                } else if (s[1] == '_') {
                    count++;
                }
            }
        }
        cout << count << "\n";
        return 0;
    } else {
        int start = (int) std::pow(10, l - 1);
        int end = (int) std::pow(10, l);
        int count = 0;
        for (int i = start; i < end; i += 25) {
            std::string str = std::to_string(i);
            std::set<char> set_chars;
            bool flag = true;
            for (int j = 0; j < l; j++) {
                if (s[j] == '_') continue;
                else if (s[j] == 'X') {
                    set_chars.insert(str[j]);
                } else if (s[j] != str[j]) {
                    flag = false;
                    break;
                }
            }
            if (flag && set_chars.size() < 2) {
                count++;
            }
        }
        cout << count << "\n";
    }
    return 0;
}
